//! World generation against the reference harness: every world of the hidden matrix (matrix, noise and both extra
//! seed groups) and two seeds of every public shape are rebuilt and each section's canonical text is compared, by
//! digest and count, with the vectors the reference harness produced (`data/suite_worlds.txt`, generated by
//! `gen_suite_worlds.py`). A failure names the world and the section. Set `WORLD_DUMP_DIR` to write the canonical
//! text of every failing section for comparison with the script's `dump` mode.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing,
    clippy::cast_possible_truncation,
    clippy::too_many_lines
)]

use std::collections::BTreeMap;

use vinc_sim::suite::world::canon::sections;
use vinc_sim::suite::world::{
    self, Params, SCENARIOS, SeedSet, Variant, add_adversary, adversary_for, build, variants,
};

mod scenario_support;

const VECTORS: &str = include_str!("data/suite_worlds.txt");
const PUBLIC_SEEDS: [u64; 2] = [1, 2];

type Expected = BTreeMap<(String, String, u64), Vec<(String, usize, String)>>;

fn expected() -> Expected {
    let mut out: Expected = BTreeMap::new();
    for l in VECTORS.lines().filter(|l| l.starts_with("world ")) {
        let f: Vec<&str> = l.split(' ').collect();
        out.entry((f[1].to_string(), f[2].to_string(), f[3].parse().unwrap()))
            .or_default()
            .push((f[4].to_string(), f[5].parse().unwrap(), f[6].to_string()));
    }
    out
}

fn set_name(s: SeedSet) -> &'static str {
    match s {
        SeedSet::Matrix => "matrix",
        SeedSet::Noise => "noise",
        SeedSet::Extra1 => "extra1",
        SeedSet::Extra2 => "extra2",
    }
}

/// Rebuilds `v` and compares it with the vector lines of `(name, id, seed)`; returns the failures.
fn check(name: &str, v: &Variant, exp: &Expected) -> Vec<String> {
    let key = (name.to_string(), v.id.to_string(), v.seed);
    let Some(want) = exp.get(&key) else {
        return vec![format!("{name} {} seed {}: no vectors", v.id, v.seed)];
    };
    let w = match build(v) {
        Ok(w) => w,
        Err(e) => return vec![format!("{name} {} seed {}: generation failed: {e}", v.id, v.seed)],
    };
    let got = sections(&w);
    let mut bad = Vec::new();
    if got.len() != want.len() {
        bad.push(format!(
            "{name} {} seed {}: {} sections, vectors have {}",
            v.id,
            v.seed,
            got.len(),
            want.len()
        ));
    }
    for (g, (sec, count, digest)) in got.iter().zip(want) {
        assert_eq!(g.name, sec, "section order");
        if g.count != *count || g.digest() != *digest {
            bad.push(format!(
                "{name} {} seed {} section {sec}: count {} (want {count}), digest {} (want {digest})",
                v.id,
                v.seed,
                g.count,
                g.digest()
            ));
            if let Ok(dir) = std::env::var("WORLD_DUMP_DIR") {
                std::fs::create_dir_all(&dir).unwrap();
                std::fs::write(format!("{dir}/{name}_{}_{}_{sec}.json", v.id, v.seed), &g.text).unwrap();
            }
        }
    }
    bad
}

fn run_set(set: SeedSet) {
    let exp = expected();
    let vs: Vec<Variant> = variants().into_iter().filter(|v| v.set == set).collect();
    assert_eq!(vs.len(), 24, "a seed group has 24 entries");
    let bad: Vec<String> = vs.iter().flat_map(|v| check(set_name(set), v, &exp)).collect();
    assert!(bad.is_empty(), "{} mismatches:\n{}", bad.len(), bad.join("\n"));
}

#[test]
fn matrix_worlds_match_the_reference() {
    run_set(SeedSet::Matrix);
}

#[test]
fn noise_worlds_match_the_reference() {
    run_set(SeedSet::Noise);
}

#[test]
fn first_extra_seed_worlds_match_the_reference() {
    run_set(SeedSet::Extra1);
}

#[test]
fn second_extra_seed_worlds_match_the_reference() {
    run_set(SeedSet::Extra2);
}

#[test]
fn public_shape_worlds_match_the_reference() {
    let exp = expected();
    let mut bad = Vec::new();
    for id in SCENARIOS {
        for seed in PUBLIC_SEEDS {
            let v = Variant {
                id,
                variant: 1,
                set: SeedSet::Matrix,
                seed,
                params: Params::new(),
            };
            bad.extend(check("public", &v, &exp));
        }
    }
    assert!(bad.is_empty(), "{} mismatches:\n{}", bad.len(), bad.join("\n"));
}

#[test]
fn every_vector_world_is_checked() {
    let exp = expected();
    let groups = ["matrix", "noise", "extra1", "extra2"];
    let in_matrix = exp.keys().filter(|k| groups.contains(&k.0.as_str())).count();
    assert_eq!(in_matrix, 96);
    assert_eq!(
        exp.keys().filter(|k| k.0 == "public").count(),
        SCENARIOS.len() * PUBLIC_SEEDS.len()
    );
}

#[test]
fn matrix_shape_is_the_reference_one() {
    let vs = variants();
    assert_eq!(vs.len(), 96);
    for set in [SeedSet::Matrix, SeedSet::Noise, SeedSet::Extra1, SeedSet::Extra2] {
        let g: Vec<&Variant> = vs.iter().filter(|v| v.set == set).collect();
        assert_eq!(g.len(), 24);
        for id in SCENARIOS {
            let of: Vec<u8> = g.iter().filter(|v| v.id == id).map(|v| v.variant).collect();
            assert_eq!(of, vec![1, 2], "{id}: two variants per scenario");
        }
    }
    let seeds = |set| vs.iter().filter(|v| v.set == set).map(|v| v.seed).collect::<Vec<_>>();
    let (m, n) = (seeds(SeedSet::Matrix), seeds(SeedSet::Noise));
    assert_eq!(seeds(SeedSet::Extra1), m.iter().map(|s| s + 1).collect::<Vec<_>>());
    assert_eq!(seeds(SeedSet::Extra2), n.iter().map(|s| s + 50).collect::<Vec<_>>());
    assert!(
        m.iter().all(|s| !n.contains(s)),
        "noise seeds are disjoint from the matrix seeds"
    );
}

#[test]
fn adversary_is_deterministic_and_separate_from_the_world() {
    let v = &variants()[0];
    let bare = world::generate(v.id, &v.params, v.seed).unwrap();
    let mut a = bare.clone();
    let mut b = bare.clone();
    add_adversary(&mut a, &adversary_for(v.id), v.seed).unwrap();
    add_adversary(&mut b, &adversary_for(v.id), v.seed).unwrap();
    assert_eq!(a, b);
    assert_eq!(a.sites, bare.sites);
    assert_eq!(a.intents, bare.intents);
    assert!(a.adversary.is_some() && bare.adversary.is_none());
    assert!(
        a.adversary_env
            .windows(2)
            .all(|w| (w[0].0, w[0].1, w[0].2) <= (w[1].0, w[1].1, w[1].2))
    );
}

#[test]
fn unknown_scenario_is_an_error() {
    assert!(world::generate("S7", &Params::new(), 1).is_err());
}

/// The default run of S6 is the first variant's `extra1` seed (86018, not the matrix seed 86017 that depends on the
/// draw of the link loss), and every other scenario keeps its matrix seed. Only the default run is pinned: the full
/// run selects all 96 seeds.
#[test]
fn default_selection_of_the_low_bandwidth_scenario_is_its_extra1_seed() {
    if scenario_support::full() {
        return;
    }
    let s6 = scenario_support::selected(&["S6"]);
    assert_eq!(s6.len(), 1);
    assert_eq!((s6[0].variant, s6[0].set, s6[0].seed), (1, SeedSet::Extra1, 86018));
    let s1 = scenario_support::selected(&["S1"]);
    assert_eq!(s1.len(), 1);
    assert_eq!((s1[0].variant, s1[0].set), (1, SeedSet::Matrix));
    assert_eq!(
        s1[0].seed,
        variants()
            .iter()
            .find(|v| v.id == "S1" && v.set == SeedSet::Matrix && v.variant == 1)
            .unwrap()
            .seed
    );
}
